text:
{
 "reason": {
  "es": "内閣《ないかく》は、国立公園《こくりつこうえん》などの自然《しぜん》を守《まも》りながら、地域《ちいき》が自分《じぶん》たちで工夫《くふう》して、公園《こうえん》をもっと使《つか》ってもらえるようにするためとしている。そのために、よい自然《しぜん》の体験《たいけん》をすすめたり、公園《こうえん》の中心《ちゅうしん》になる場所《ばしょ》をよくしたりする話《はな》し合《あ》いの会《かい》（協議会《きょうぎかい》）と、計画《けいかく》を認《みと》めるしくみをつくる。また、公園《こうえん》の使《つか》い方《かた》のきまりを強《つよ》くする、としている。",
  "hs": "内閣は、国立公園などを保護しながら、地域が主体的に取り組んで利用を増やすためとしている。そのために、質の高い自然体験活動をすすめたり、利用の拠点《きょてん》（中心となる場所）の質を高めたりするための協議会をつくる制度と、計画を認定する制度をつくる。また、利用についての規制を強めるなどの措置《そち》をとる、としている。",
  "std": "内閣は、国立公園などを保護しつつ、地域の主体的な取り組みによって利用の増進を図るためとしている。そのために、質の高い自然体験活動の促進や利用拠点の質の向上のための協議会の設置と計画の認定に関する制度を創設し、利用のための規制を強化するなどの措置が必要だとしている。",
  "univ": "内閣は、国立公園等を保護しつつ地域の主体的な取組による利用の増進を図るため、質の高い自然体験活動の促進又は利用拠点の質の向上のための協議会の設置及び計画の認定に係る制度の創設、利用のための規制の強化等の措置を講ずる必要があるためとしている。"
 },
 "who": {
  "es": "話《はな》し合《あ》いの会《かい》（協議会《きょうぎかい》）をつくれる市町村《しちょうそん》など。その計画《けいかく》を認《みと》める環境大臣《かんきょうだいじん》（国立公園《こくりつこうえん》）と都道府県《とどうふけん》の知事《ちじ》（国定公園《こくていこうえん》）。認《みと》められた計画《けいかく》で事業《じぎょう》をする人《ひと》。公園《こうえん》の決《き》められた場所《ばしょ》で、野生《やせい》の動物《どうぶつ》にえさをあげるなどする人《ひと》。公園《こうえん》の事業《じぎょう》をゆずる人《ひと》・受《う》けつぐ人《ひと》。公園《こうえん》を管理《かんり》する団体《だんたい》に選《えら》ばれる法人《ほうじん》。",
  "hs": "協議会をつくることができる市町村など。計画の認定をする環境《かんきょう》大臣（国立公園）と都道府県知事（国定公園）。認定された計画にもとづく事業をする者（特別地域などでの行為《こうい》の許可などが不要になる）。国立公園・国定公園の特別地域などで、野生動物に餌《えさ》をあたえるなど利用のさまたげになるおそれのある行為《こうい》をする人。公園事業をゆずる者・受けつぐ者。公園管理団体として指定される法人。",
  "std": "協議会を組織できる市町村等。計画を認定する環境大臣（国立公園）と都道府県知事（国定公園）。認定を受けた計画に基づき事業を行う者（特別地域等での行為の許可等が不要になる）。国立・国定公園の特別地域などで、野生動物に餌を与えるなど公園の利用に支障を及ぼすおそれのある行為をする人。公園事業を譲渡する者・承継する者。公園管理団体として指定される法人。",
  "univ": "単独で又は共同して協議会を組織することができる市町村等。利用拠点整備改善計画・自然体験活動促進計画の認定を行う環境大臣（国立公園）及び都道府県知事（国定公園）。認定を受けた計画に係る事業を行う者（特別地域等における行為に係る許可等を要しない）。国立公園又は国定公園の特別地域、海域公園地区又は集団施設地区内において、野生動物に餌を与えることその他の野生動物の生態に影響を及ぼす行為であって、公園の利用に支障を及ぼすおそれのあるものを行う者。公園事業を譲渡する者及び地位を承継する者。公園管理団体として指定される法人。"
 },
 "committee": {
  "es": "衆議院《しゅうぎいん》の環境委員会《かんきょういいんかい》では、3月《がつ》19日《にち》に大臣《だいじん》から説明《せつめい》を聞《き》き、4月《がつ》2日《ふつか》に質問《しつもん》をした。意見《いけん》をのべあったあと、賛成《さんせい》が多《おお》く、そのまま認《みと》めることにした。委員会《いいんかい》からの注文《ちゅうもん》（附帯決議《ふたいけつぎ》）もつけた。参議院《さんぎいん》の環境委員会《かんきょういいんかい》では、法律《ほうりつ》を変《か》える意味《いみ》と効果《こうか》、話《はな》し合《あ》いの会《かい》のメンバーと進《すす》め方《かた》、国立公園《こくりつこうえん》の中《なか》の空《あ》き家《や》の問題《もんだい》、部屋《へや》ごとに売《う》るホテルなどについて質問《しつもん》があった。日本共産党《にほんきょうさんとう》が反対《はんたい》の意見《いけん》をのべた。賛成《さんせい》が多《おお》く、そのまま認《みと》めることにし、附帯決議《ふたいけつぎ》もつけた。",
  "hs": "衆議院の環境《かんきょう》委員会では、3月18日に付託《ふたく》（審査《しんさ》をまかされること）され、19日に小泉｜環境《かんきょう》大臣から趣旨《しゅし》の説明を聞き、4月2日に質疑をした。討論のあと採決し、賛成多数で原案のとおり可決すべきものとした。附帯《ふたい》決議（委員会がつけた注文）もつけた。参議院の環境《かんきょう》委員会では、法改正の意義と効果、協議会の構成員と運営のあり方、国立公園の中の廃屋《はいおく》（使われなくなった建物）への対応、分譲型《ぶんじょうがた》ホテルのあり方などについて質疑があった。討論では日本共産党が反対の意見を述べた。採決の結果、多数で原案どおり可決すべきものとし、附帯《ふたい》決議もつけた。",
  "std": "衆議院環境委員会では、3月18日に付託され、19日に小泉環境大臣から趣旨説明を聴取し、4月2日に質疑を行った。討論の後、採決の結果、賛成多数で原案のとおり可決すべきものと決し、附帯決議が付された。参議院環境委員会では、法改正の意義と効果、設置される協議会の構成員と運営の在り方、国立公園における廃屋への対応策、分譲型ホテルの在り方などについて質疑が行われた。討論では日本共産党が反対の意見を述べ、採決の結果、多数で原案どおり可決すべきものと決定し、附帯決議が付された。",
  "univ": "衆議院環境委員会においては、3月18日に付託され、翌19日に小泉環境大臣から趣旨の説明を聴取し、4月2日に質疑を行った。同日、質疑を終局した後、討論を行い、採決の結果、賛成多数をもって原案のとおり可決すべきものと決し、附帯決議が付された。参議院環境委員会においては、法改正の意義及びその効果、設置される協議会の構成員及び運営の在り方、国立公園における廃屋への対応策、分譲型ホテルの在り方等について質疑が行われた。討論では日本共産党を代表して山下委員より反対する旨の意見が述べられ、採決の結果、多数をもって原案どおり可決すべきものと決定し、附帯決議が付された。"
 },
 "views": [
  {
   "side": "反対",
   "group": "日本共産党",
   "where": "衆議院 環境委員会、参議院 環境委員会",
   "text": {
    "es": "日本共産党《にほんきょうさんとう》は、衆議院《しゅうぎいん》と参議院《さんぎいん》の環境委員会《かんきょういいんかい》で、次《つぎ》のことを理由《りゆう》に反対《はんたい》した。自然《しぜん》を守《まも》るより使《つか》うことを重《おも》く見《み》る国《くに》の取《と》り組《く》みを、全国《ぜんこく》の公園《こうえん》に広《ひろ》げるものだ。事業者《じぎょうしゃ》が中心《ちゅうしん》の話《はな》し合《あ》いの会《かい》が、公園《こうえん》の計画《けいかく》を変《か》えるよう提案《ていあん》できる。住民《じゅうみん》などが会《かい》に入《はい》れるとはかぎらない。環境大臣《かんきょうだいじん》が短《みじか》い時間《じかん》で答《こた》えを出《だ》すことになり、生《い》き物《もの》への影響《えいきょう》を見《み》のがすおそれがある。",
    "hs": "日本共産党は、衆議院と参議院の環境《かんきょう》委員会の討論で、次のことを理由に反対した。環境《かんきょう》の保護より利用の促進《そくしん》にかたよる「国立公園｜満喫《まんきつ》プロジェクト」を、全国の自然公園に広げるものだ。事業者中心の協議会が公園計画の変更《へんこう》を提案できる。協議会は事業者と自治体だけで構成でき、住民などの参加は自治体が認めた場合に限られる。環境《かんきょう》大臣に応答の義務が課され、短い時間で結論を求められると、生態系への影響《えいきょう》を見過ごすおそれがある、と述べた。",
    "std": "日本共産党は、衆参両院の環境委員会の討論で、本法案が、環境の保護よりも利用の促進に偏っているとする「国立公園満喫プロジェクト」を全国の自然公園に展開するものだとして反対した。事業者を中心とする協議会が公園計画の変更を提案できることや、協議会を事業者と自治体だけで構成でき、環境保護団体や住民の参加が自治体が認めた場合に限られることを挙げた。また、環境大臣に応答義務が課され、短時間で結論を求められると、生態系への影響を見過ごしかねないと述べた。",
    "univ": "日本共産党は、衆議院環境委員会（田村貴昭委員）及び参議院環境委員会（山下芳生委員）の討論で、本法案が、環境の保護よりも利用の促進に偏っているとする国立公園満喫プロジェクトを全国の自然公園に展開するためのものであるとして反対した。事業者を中心として組織された協議会が公園計画の変更を提案できることで、公園計画の策定という国の責任を事実上事業者に委ねることになり、協議会も事業者と自治体だけで構成でき、地域の環境保護団体や有識者、住民の参加は自治体が認めた場合に限られると述べた。また、環境大臣に応答義務が課され、従来に比べ短時間で結論を求められると、事業実施に伴う生態系への影響を見過ごすことになりかねないと述べた。"
   }
  }
 ],
 "no_debate": false
}
